5	import { transformSync } from "esbuild";
6	import { mkdirSync, writeFileSync } from "node:fs";
7	import assert from "node:assert/strict";
8	import { createRequire } from "node:module";
9	
10	mkdirSync(".build", { recursive: true });
11	const jsx = readFileSyncText("src/PricingTable.jsx");
12	const js = transformSync(jsx, { loader: "jsx", jsx: "automatic", format: "esm" }).code;
13	writeFileSync(".build/PricingTable.mjs", js);
14	const { PricingTable } = await import("./.build/PricingTable.mjs");
15	
16	const items = [
17	  { name: "Espresso", qty: 2, price: 1.5 },
18	  { name: "Cappuccino", qty: 3, price: 4.0 },
19	  { name: "Brioche", qty: 1, price: 2.5 },
20	];
21	const html = renderToString(React.createElement(PricingTable, { items, currency: "EUR" }));
22	
23	assert.match(html, /<table[^>]*>/, "must render a <table>");
24	assert.match(html, /<thead[^>]*>[\s\S]*?<th[^>]*>\s*Item\s*<\/th>[\s\S]*?<th[^>]*>\s*Qty\s*<\/th>[\s\S]*?<th[^>]*>\s*Price\s*<\/th>[\s\S]*?<\/thead>/, "thead must have Item, Qty, Price headers in order");
25	assert.match(html, /<tbody[^>]*>[\s\S]*?<tr/, "tbody rows must use <tr>");
26	assert.match(html, /Espresso[\s\S]*?Cappuccino/, "rows keep input order");
27	assert.match(html, />\s*3\.00\s*EUR\s*</, "Espresso line price 2 x 1.50 = 3.00 EUR, currency after amount, two decimals");
28	assert.match(html, />\s*12\.00\s*EUR\s*</, "Cappuccino line price 3 x 4.00 = 12.00 EUR");
29	assert.match(html, />\s*2\.50\s*EUR\s*</, "Brioche line price 1 x 2.50 = 2.50 EUR");
30	assert.match(html, /Total:\s*17\.50\s*EUR/, "correct grand total 17.50 EUR (qty x price summed)");
31	
32	console.log("RENDER_CHECK_OK");
33	
